import{_ as a,o as r,c as o,ag as t}from"./chunks/framework.CrXGS008.js";const f=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"fr/faq.md","filePath":"fr/faq.md"}'),s={name:"fr/faq.md"};function n(d,e,i,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="la-console-affiche-you-lack-the-required-entitlement" tabindex="-1">La console affiche <code>You lack the required entitlement</code> <a class="header-anchor" href="#la-console-affiche-you-lack-the-required-entitlement" aria-label="Permalink to &quot;La console affiche `You lack the required entitlement`&quot;">​</a></h2><p>Le script n&#39;est pas lié au compte Cfx.re propriétaire de la clé de licence du serveur. Vérifiez dans <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> que le compte qui a acheté le script est bien celui qui a créé la clé de <code>sv_licenseKey</code>. Les droits sont lus au démarrage du serveur : après un nouvel achat, redémarrez tout le serveur, un <code>restart</code> de la ressource ne suffit pas.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p><code>nay_lib</code> doit démarrer avant tous les scripts Nayretis, et les deux dossiers doivent être dans votre dossier <code>resources</code>. Vérifiez l&#39;ordre des lignes <code>ensure</code> dans <code>server.cfg</code> : <code>ensure nay_lib</code> vient en premier, après votre framework, votre inventaire et votre target.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Démarrez <code>nay_lib</code> après votre framework. Si la détection échoue encore, forcez-la dans <code>server.cfg</code>, par exemple <code>setr nay:framework &quot;esx&quot;</code>. Les valeurs sont sur la page <a href="/fr/bridge/">Bridge</a>. Votre framework n&#39;est pas pris en charge ? Écrivez un <a href="/fr/bridge/custom">adaptateur personnalisé</a>.</p><h2 id="erreurs-de-base-de-donnees-au-demarrage" tabindex="-1">Erreurs de base de données au démarrage <a class="header-anchor" href="#erreurs-de-base-de-donnees-au-demarrage" aria-label="Permalink to &quot;Erreurs de base de données au démarrage&quot;">​</a></h2><p><code>oxmysql</code> doit démarrer avant <code>nay_lib</code> et être connecté à votre base (<code>mysql_connection_string</code> dans <code>server.cfg</code>). Les tables sont créées au premier démarrage : l&#39;utilisateur de la base doit avoir le droit de créer des tables.</p><h2 id="comment-changer-la-langue" tabindex="-1">Comment changer la langue ? <a class="header-anchor" href="#comment-changer-la-langue" aria-label="Permalink to &quot;Comment changer la langue ?&quot;">​</a></h2><p>Ouvrez <code>/nay</code>, puis <strong>Nayretis</strong>, puis <strong>Langue</strong>. L&#39;anglais, le français, l&#39;espagnol, le portugais, le polonais et l&#39;allemand sont inclus, et la langue s&#39;applique à tous les scripts Nayretis. <code>setr nay:locale &quot;fr&quot;</code> dans <code>server.cfg</code> fixe la langue utilisée tant que personne ne la change en jeu.</p><h2 id="quels-fichiers-puis-je-modifier" tabindex="-1">Quels fichiers puis-je modifier ? <a class="header-anchor" href="#quels-fichiers-puis-je-modifier" aria-label="Permalink to &quot;Quels fichiers puis-je modifier ?&quot;">​</a></h2><ul><li><code>config.lua</code> de chaque script : des valeurs de départ facultatives. Elles s&#39;appliquent tant qu&#39;un réglage n&#39;a pas été changé dans <code>/nay</code>, et <strong>Réinitialiser</strong> revient à elles.</li><li><code>locales/*.json</code> : tous les textes affichés aux joueurs.</li><li><code>nay_lib/bridge/custom.lua</code> : votre propre adaptateur de framework.</li></ul><p>Le reste du code est protégé par l&#39;escrow Cfx.</p><h2 id="nay-lib-se-connecte-t-il-a-quelque-chose" tabindex="-1">nay_lib se connecte-t-il à quelque chose ? <a class="header-anchor" href="#nay-lib-se-connecte-t-il-a-quelque-chose" aria-label="Permalink to &quot;nay_lib se connecte-t-il à quelque chose ?&quot;">​</a></h2><p>Au démarrage, <code>nay_lib</code> lit un fichier de versions public (<code>https://versions.nayretis.com/versions.json</code>) et indique dans la console quand une mise à jour est disponible. Désactivez-le avec <code>set nay:versionCheck false</code>. Rien d&#39;autre ne quitte votre serveur, sauf si vous activez l&#39;<a href="/fr/nay-lib/api">API HTTP</a> ou ajoutez des <a href="/fr/nay-lib/webhooks">webhooks</a>.</p><h2 id="ou-trouver-de-l-aide" tabindex="-1">Où trouver de l&#39;aide ? <a class="header-anchor" href="#ou-trouver-de-l-aide" aria-label="Permalink to &quot;Où trouver de l&#39;aide ?&quot;">​</a></h2><p>Ouvrez un post dans <code>#support</code> sur le <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord Nayretis</a>, un post par problème, avec le script et sa version, votre framework, inventaire et target, et les erreurs de la console serveur et de F8.</p>',18)])])}const h=a(s,[["render",n]]);export{f as __pageData,h as default};
